import { randomBytes } from "node:crypto";

export const E2E_API_PORT = 3100;
export const E2E_WEB_PORT = 4180;
export const E2E_BASE_URL = `http://localhost:${E2E_WEB_PORT}`;
export const E2E_ADMIN_USERNAME = "admin";

/**
 * One admin password per Playwright invocation: generated by the config in the main process
 * and inherited through the environment by the stack, Vite and the test workers. Never committed.
 */
export function adminPassword(): string {
  process.env.E2E_ADMIN_PASSWORD ??= randomBytes(12).toString("base64url");
  return process.env.E2E_ADMIN_PASSWORD;
}

export function e2eEnvironment(): Record<string, string> {
  return {
    NODE_ENV: "test",
    DATABASE_URL: process.env.E2E_DATABASE_URL ?? "postgresql://agentflow:agentflow@localhost:5432/agentflow_e2e_test",
    REDIS_URL: process.env.E2E_REDIS_URL ?? "redis://localhost:6379/1",
    API_PORT: String(E2E_API_PORT),
    AGENTFLOW_ADMIN_USERNAME: E2E_ADMIN_USERNAME,
    AGENTFLOW_ADMIN_PASSWORD: adminPassword(),
    // Short leases so a crashed worker's step is re-dispatched within seconds.
    OPERATION_LEASE_MS: "4000",
    LEASE_HEARTBEAT_MS: "1000",
    SCHEDULER_POLL_MS: "500",
    OUTBOX_POLL_MS: "200",
    DISPATCH_RECOVERY_MS: "2000",
  };
}
